# ============================================================
# 12. HWPX 최종 생성 함수
# ============================================================

def generate_hwpx(title, content):

    current_time = datetime.datetime.now().strftime(
        "%Y-%m-%d %H:%M"
    )

    # --------------------------------------------------------
    # HWPX 문서 생성
    # --------------------------------------------------------

    doc = HwpxDocument.new()

    # --------------------------------------------------------
    # 페이지 설정
    # --------------------------------------------------------

    try:

        section = doc.sections[0]

        # A4 세로
        section.page_width = 210000
        section.page_height = 297000

        # 여백
        section.margin_top = 18000
        section.margin_bottom = 18000
        section.margin_left = 20000
        section.margin_right = 20000

    except Exception:
        # 라이브러리 버전에 따라 페이지 설정 API가 다를 수 있으므로
        # 문서 생성 자체는 계속 진행
        pass

    # --------------------------------------------------------
    # AI 답변 파싱
    # --------------------------------------------------------

    sections = _parse_report_sections(content)

    risks = _parse_risks(
        sections["risks"]
    )

    laws = _parse_laws(
        sections["laws"]
    )

    actions = _parse_actions(
        sections["actions"]
    )

    # ========================================================
    # 표지 / 문서 상단
    # ========================================================

    p = doc.add_paragraph("")

    p.add_run(
        "한국환경공단(K-ECO)",
        bold=True,
        font="맑은 고딕",
        size=16
    )

    p = doc.add_paragraph("")

    p.add_run(
        "수도권서부환경본부",
        bold=True,
        font="맑은 고딕",
        size=13
    )

    # --------------------------------------------------------
    # 보고서 제목
    # --------------------------------------------------------

    p = doc.add_paragraph("")

    p.add_run(
        "기술 자문 및 안전 점검 보고서",
        bold=True,
        font="맑은 고딕",
        size=20
    )

    p = doc.add_paragraph("")

    p.add_run(
        "AI 안전 기술 자문 결과",
        font="맑은 고딕",
        size=11
    )

    doc.add_paragraph("")


    # ========================================================
    # 문서 기본정보 표
    # ========================================================

    info_table = doc.add_table(
        rows=4,
        cols=2
    )

    info_items = [
        ("시행일자", current_time),
        ("대상", "현장 작업 관리자 및 협력업체 임직원"),
        ("문서 제목", title),
        ("작성 부서", "한국환경공단 수도권서부환경본부")
    ]

    for row, (label, value) in enumerate(info_items):

        _set_cell(
            info_table,
            row,
            0,
            label,
            bold=True,
            size=9
        )

        _set_cell(
            info_table,
            row,
            1,
            value,
            size=9
        )

    doc.add_paragraph("")


    # ========================================================
    # 1. 점검 개요
    # ========================================================

    _add_section_title(
        doc,
        1,
        "점검 개요"
    )

    if sections["overview"]:

        for line in sections["overview"]:
            _add_normal_paragraph(
                doc,
                line
            )

    else:

        _add_normal_paragraph(
            doc,
            "AI 안전 기술 자문 요청사항 및 점검 대상에 대한 개요입니다."
        )

    doc.add_paragraph("")


    # ========================================================
    # 2. 주요 위험요인
    # ========================================================

    _add_section_title(
        doc,
        2,
        "주요 위험요인"
    )

    _add_risk_table(
        doc,
        risks
    )


    # ========================================================
    # 3. 관련 법령 및 기준
    # ========================================================

    _add_section_title(
        doc,
        3,
        "관련 법령 및 기준"
    )

    _add_law_table(
        doc,
        laws
    )


    # ========================================================
    # 4. 권장 조치사항
    # ========================================================

    _add_section_title(
        doc,
        4,
        "권장 조치사항"
    )

    _add_action_table(
        doc,
        actions
    )


    # ========================================================
    # 5. 현장 적용 시 유의사항
    # ========================================================

    _add_section_title(
        doc,
        5,
        "현장 적용 시 유의사항"
    )

    if sections["cautions"]:

        for line in sections["cautions"]:

            _add_normal_paragraph(
                doc,
                line
            )

    else:

        _add_normal_paragraph(
            doc,
            "작업 전 관련 위험요인 및 안전조치 이행 여부를 확인하고, "
            "현장 여건에 따라 필요한 추가 안전조치를 실시하여야 합니다."
        )

    doc.add_paragraph("")


    # ========================================================
    # 6. 종합 의견
    # ========================================================

    _add_section_title(
        doc,
        6,
        "종합 의견"
    )

    if sections["opinion"]:

        for line in sections["opinion"]:

            _add_normal_paragraph(
                doc,
                line
            )

    else:

        _add_normal_paragraph(
            doc,
            "상기 위험요인 및 권장 조치사항을 작업 전에 확인하고 "
            "필요한 안전조치를 우선적으로 이행하시기 바랍니다."
        )

    doc.add_paragraph("")


    # ========================================================
    # 7. 행정 및 조치사항
    # ========================================================

    _add_section_title(
        doc,
        7,
        "행정 및 조치사항"
    )

    _add_normal_paragraph(
        doc,
        "상기 위험요소를 현장 작업 전 반드시 숙지하고 "
        "관련 안전조치를 철저히 이행하여 주시기 바랍니다."
    )

    _add_normal_paragraph(
        doc,
        "안전조치가 충분히 이루어지지 않은 상태에서 작업을 진행하지 않도록 "
        "현장 관리자는 작업 전 안전조치 이행 여부를 확인하여야 합니다."
    )

    _add_normal_paragraph(
        doc,
        "현장 안전관리자는 본 보고서의 내용을 바탕으로 "
        "작업 전 안전교육(TBM)을 실시하여 작업자에게 주요 위험요인과 "
        "안전조치 사항을 전달하여 주시기 바랍니다."
    )

    doc.add_paragraph("")
    doc.add_paragraph("")


    # ========================================================
    # 결재 / 발신 명의
    # ========================================================

    p = doc.add_paragraph("")

    p.add_run(
        "한국환경공단",
        bold=True,
        font="맑은 고딕",
        size=12
    )

    p = doc.add_paragraph("")

    p.add_run(
        "수도권서부환경본부",
        bold=True,
        font="맑은 고딕",
        size=11
    )


    # ========================================================
    # 문서 저장
    # ========================================================

    buffer = io.BytesIO()

    doc.save_to_stream(buffer)

    buffer.seek(0)

    return buffer.getvalue()

# --- Base64 이미지 변환 함수 ---
def get_base64_image(image_path):
    try:
        resolved_path = Path(image_path)
        if not resolved_path.is_absolute():
            resolved_path = Path(__file__).resolve().parent / resolved_path
        with open(resolved_path, "rb") as img_file:
            return base64.b64encode(img_file.read()).decode()
    except Exception:
        return ""

img_base64 = get_base64_image("Keco_logo.png")
mascot_base64 = get_base64_image("puru_guru.png")
